namespace Kaitai\Struct\Tests;

class ExprCalcIntTernaryTest extends TestCase {
    public function testExprCalcIntTernary() {
        $r = ExprCalcIntTernary::fromFile(self::SRC_DIR_PATH . '/expr_calc_int_ternary.bin');
        $this->assertSame(3, $r->u4Val());
        $this->assertSame(4294967301, $r->u8Val());
        $this->assertSame(-8589934592, $r->s8Val());
        $this->assertSame(4294967301, $r->u8IoSize());
        $this->assertSame(4294967301, $r->ioSizeU8());
        $this->assertSame(-4294967296, $r->divS8IoSize());
        $this->assertSame(3, $r->ioSizeU4());
    }
}
